CREATE TRIGGER inv2_subtask_insert BEFORE INSERT ON subtasks
WHEN NEW.status <> 'done'
  AND (SELECT status FROM tasks WHERE id = NEW.task_id) = 'done'
BEGIN
  SELECT RAISE(ABORT, 'INV-2: a Done task cannot gain an open subtask');
END;

CREATE TRIGGER inv2_subtask_update BEFORE UPDATE ON subtasks
WHEN NEW.status <> 'done'
  AND (SELECT status FROM tasks WHERE id = NEW.task_id) = 'done'
BEGIN
  SELECT RAISE(ABORT, 'INV-2: a Done task cannot hold an open subtask');
END;

CREATE TRIGGER inv2_task_insert BEFORE INSERT ON tasks
WHEN NEW.status = 'done'
  AND EXISTS (
    SELECT 1 FROM subtasks WHERE task_id = NEW.id AND status <> 'done'
  )
BEGIN
  SELECT RAISE(ABORT, 'INV-2: this task has subtasks that are not Done');
END;

CREATE TRIGGER inv2_task_update BEFORE UPDATE ON tasks
WHEN NEW.status = 'done'
  AND EXISTS (
    SELECT 1 FROM subtasks WHERE task_id = NEW.id AND status <> 'done'
  )
BEGIN
  SELECT RAISE(ABORT, 'INV-2: this task has subtasks that are not Done');
END;

CREATE TRIGGER inv7_idea_insert BEFORE INSERT ON ideas
WHEN EXISTS (SELECT 1 FROM idea_tombstones WHERE id = NEW.id)
BEGIN
  SELECT RAISE(ABORT, 'INV-7: this Idea id is tombstoned');
END;

CREATE TRIGGER inv7_idea_update BEFORE UPDATE ON ideas
WHEN EXISTS (SELECT 1 FROM idea_tombstones WHERE id = NEW.id)
BEGIN
  SELECT RAISE(ABORT, 'INV-7: this Idea id is tombstoned');
END;

CREATE TRIGGER inv7_tombstone_insert BEFORE INSERT ON idea_tombstones
WHEN EXISTS (SELECT 1 FROM ideas WHERE id = NEW.id)
BEGIN
  SELECT RAISE(ABORT, 'INV-7: this Idea is still present; delete it first');
END;
